INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (363391, 14807, 'South China Morning Post', 'en', 'Can China follow its own ‘technological path’ amid growing AI rivalry with US?', 'https://www.scmp.com/news/china/diplomacy/article/3364296/can-china-follow-its-own-technological-path-amid-growing-ai-rivalry-us', 'China’s ability to set its own technological course in the face of sustained US export restrictions may be the key factor in the two countries’ contest over artificial intelligence (AI), a prominent analyst has argued. Zheng Yongnian, dean of the school of public policy at the Chinese University of Hong Kong (Shenzhen), made the case in his preface to The Rise of Atlas, a new book about the development of Huawei Technologies’ Atlas 950 SuperPoD computing system. The system, which Huawei...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/17/6c860e52-e519-401c-ba58-2802dab092ea_f8fe5708.jpg?itok=YPVn8K7v&v=1786959268', '2026-08-17T10:00:16+00:00', '2026-08-17T21:43:51.003922'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (363405, 14807, 'South China Morning Post', 'en', 'China’s self-driving push gains ground in Europe as Momenta, Pony.ai expand', 'https://www.scmp.com/business/banking-finance/article/3364257/chinas-self-driving-push-gains-ground-europe-momenta-ponyai-expand', 'China’s autonomous-driving ambitions are winning growing recognition in Europe, with Deutsche Bank raising its target price for Momenta following a key regulatory breakthrough, and Pony.ai expanding its European robotaxi roll-out alongside Uber Technologies. In a research note released on Monday, Deutsche Bank analyst Bin Wang saw Momenta as the “No 1 independent autonomous-driving solution provider globally”, particularly in the urban “navigation on autopilot” (NOA) segment. “Momenta’s market...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/17/93722640-d67c-49b2-b6e1-0dd7602366c1_869c6790.jpg?itok=F6GjiqTn&v=1786947594', '2026-08-17T07:00:11+00:00', '2026-08-17T21:43:51.166032'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
